import java.util.*;class A{String s(boolean P,String[]I){List<Integer>a=new Stack<>(),b=new Stack<>();for(var l:I){var S=new Scanner(l);a.add(S.nextInt());b.add(S.nextInt());}long r=0;if(P){a.sort(null);b.sort(null);for(int i=a.size();i-->0;)r+=Math.abs(a.get(i)-b.get(i));}else for(int x:a)for(int y:b)r+=x==y?x:0;return r+"";}}
